// FC 27 LE Turbo GUI - named choices for the teamkits font and layout ids (Teams > Colours, 2.11 K1).
//
// teamkits.jerseynamefonttype (0..511), numberfonttype (0..511), shortsnumberfonttype (0..511) and jerseynamelayouttype
// (0..255) are plain ids. Turbo cannot ship fonts or draw a sample, so it NAMES them two ways:
//   1. the game's own folder names (kit_fonts_data.h, generated by turbo/tools/kits3d/kit_fonts_manifest.py from the asset
//      names in the game's bundle manifests: content/character/kitnumber/chelsea_291 -> number font 291 "chelsea",
//      content/character/jerseyfonts/chelsea_153 -> name font 153 "chelsea"). No font data, no pictures.
//      INFERENCE, not yet proven in game: the folder suffix is the database id. The proof compares the id a club's live kit
//      holds with the id named after that club.
//   2. "worn by": the clubs whose live kits hold the id, computed from the loaded teamkits table (kit types 0..4: home,
//      away, goalkeeper, third, fourth). Needs no asset and shows which look a club really wears.
// shortsnumberfonttype uses the number fonts' names (the kitnumber families include *_shorts_<id> folders; inferred).
// jerseynamelayouttype 0 / 1 = "straight" / "arched" is the FIFA Kit Creator FAQ's statement for FC 26 (not measured in FC 27).
#pragma once
#include <cstdint>
#include <functional>
#include <string>
#include <vector>

namespace turbo {
namespace kitfonts {

enum class Kind { NameFont = 0, NumberFont = 1, ShortsNumberFont = 2, NameLayout = 3 };
inline constexpr int kKinds = 4;

const char* field_of(Kind k);  // the teamkits column
const char* title_of(Kind k);  // "Name font", "Number font", "Shorts number font", "Name layout"
// The widest id the schema allows (511 / 511 / 511 / 255); the picker also accepts any id the table's own field range holds
int64_t schema_max(Kind k);

// The game's own name for the id ("chelsea", "puma_2024"); "" when its manifests have none (or, for the layout, no name)
std::string game_name(Kind k, int64_t id);
// "chelsea" -> "Chelsea", "puma_2024" -> "Puma 2024"
std::string pretty_name(const std::string& raw);

// One teamkits row: the club (teamtechid), the kit type (teamkittypetechid) and the four values (-1 = unreadable)
struct KitRow {
    int64_t team = 0;
    int64_t type = 0;
    int64_t value[kKinds] = {-1, -1, -1, -1};
};
inline constexpr int64_t kLastCountedKitType = 4;  // home, away, goalkeeper, third, fourth; not referee or training kits

struct Wearer {
    std::string club;
    int kits = 0;  // this club's kits that hold the id
};
struct Entry {
    int64_t id = 0;
    int kits = 0;               // kits holding the id
    std::vector<Wearer> clubs;  // distinct clubs, most kits first, then by name
};

class Index {
public:
    using NameFn = std::function<std::string(int64_t)>;
    // Counts the rows of the types 0..kLastCountedKitType; a club the name function does not know is "team <id>"
    void build(const std::vector<KitRow>& rows, const NameFn& team_name);
    const std::vector<Entry>& entries(Kind k) const { return per_[static_cast<int>(k)]; }  // by id
    const Entry* find(Kind k, int64_t id) const;
    int kits() const { return kits_; }  // rows counted
    bool empty() const { return kits_ == 0; }

private:
    std::vector<Entry> per_[kKinds];
    int kits_ = 0;
};

// The ids the picker lists: those a counted kit holds plus those the game names, ascending
std::vector<int64_t> choice_ids(Kind k, const Index& idx);

// "worn by 3 clubs: Chelsea, Arsenal, Leicester City" / "worn by 112 clubs: A, B, C, D, E, F and 106 more" / "worn by no club in this database"
std::string worn_by(const Entry* e, size_t max_names = 6);
// One line for the combo: "291  Chelsea  -  worn by Chelsea, Arsenal and 1 more"; "7  (not named by the game)  -  worn by no club"
std::string choice_label(Kind k, int64_t id, const Entry* e);
// What the combo shows closed: the id and the name only
std::string short_label(Kind k, int64_t id);
// The filter box: every word (case-insensitive) must be in the id, the game's name or one of the clubs
bool matches(Kind k, int64_t id, const Entry* e, const std::string& filter);

}  // namespace kitfonts
}  // namespace turbo
